"""Generic finite quotient generated by literal conditional-rule application.

The caller declares finite quotient states and provides two semantic boundary
maps: a representative complete graph for each state, and a projection from a
generated target graph back to a quotient state.  This module supplies the
rest: it applies each literal rule, retains exact injective-match
multiplicities, applies the declared per-match normalization, and constructs a
rate-separated backward generator.  It contains no chemistry, slot, word, or
tree knowledge.
"""
from __future__ import annotations

from dataclasses import dataclass
from fractions import Fraction
from typing import Callable, Hashable, Mapping

import molfoundry as mf
from mfobs.core.conditions import transitions


Matrix = tuple[tuple[Fraction, ...], ...]


@dataclass(frozen=True)
class FiniteRuleChannel:
    """One literal rule and its exact normalization in a finite projection."""

    identifier: str
    rule: mf.Rule
    per_match: Fraction

    def __post_init__(self) -> None:
        if not self.identifier or self.per_match <= 0:
            raise ValueError("finite rule channels need an id and positive normalization")


@dataclass(frozen=True)
class FiniteRuleProjection:
    """Exact generators and inspectable application evidence."""

    states: tuple[Hashable, ...]
    generators: Mapping[str, Matrix]
    evidence: Mapping


def project_finite_rule_generators(
    *,
    states: tuple[Hashable, ...],
    channels: tuple[FiniteRuleChannel, ...],
    representative: Callable[[Hashable, str], object],
    project_target: Callable[[Hashable, str, object], Hashable],
    certified_zero_channels: Mapping[str, str] | None = None,
) -> FiniteRuleProjection:
    """Apply literal rules and project their products onto a finite quotient.

    ``certified_zero_channels`` is reserved for rules proved to preserve every
    quotient coordinate.  Such a rule is retained as an explicit zero
    generator without needlessly enumerating changes in discarded dimensions.
    """

    if not states or len(states) != len(set(states)):
        raise ValueError("finite quotient states must be nonempty and unique")
    if not channels or len({channel.identifier for channel in channels}) != len(channels):
        raise ValueError("finite rule channels must be nonempty and unique")
    certified_zero_channels = dict(certified_zero_channels or {})
    if set(certified_zero_channels) - {channel.identifier for channel in channels}:
        raise ValueError("zero certificate names an unknown channel")

    index = {state: position for position, state in enumerate(states)}
    generators = {}
    channel_records = []
    for channel in channels:
        rows = [[Fraction() for _ in states] for _ in states]
        source_records = []
        if channel.identifier in certified_zero_channels:
            generators[channel.identifier] = tuple(tuple(row) for row in rows)
            channel_records.append({
                "channel": channel.identifier,
                "construction": "certified zero on the quotient",
                "certificate": certified_zero_channels[channel.identifier],
                "source_states_checked_by_application": 0,
                "projected_transition_classes": 0,
            })
            continue

        projected_classes = raw_matches = generated_products = 0
        for source_index, source in enumerate(states):
            host = representative(source, channel.identifier)
            outcomes = transitions(channel.rule, host)
            aggregated: dict[Hashable, Fraction] = {}
            for target_graph, multiplicity in outcomes.items():
                target = project_target(source, channel.identifier, target_graph)
                if target not in index:
                    raise ValueError(
                        f"{channel.identifier}: target outside the declared quotient"
                    )
                rate = channel.per_match * multiplicity
                raw_matches += multiplicity
                generated_products += 1
                if target != source:
                    aggregated[target] = aggregated.get(target, Fraction()) + rate
            for target, rate in aggregated.items():
                rows[source_index][index[target]] += rate
            rows[source_index][source_index] = -sum(rows[source_index], Fraction())
            projected_classes += len(aggregated)
            source_records.append({
                "source": source,
                "generated_nonidentity_products": len(outcomes),
                "raw_injective_matches": sum(outcomes.values()),
                "projected_targets": [
                    {"target": target, "rate_coefficient": str(rate)}
                    for target, rate in sorted(aggregated.items(), key=lambda item: repr(item[0]))
                ],
            })
        generator = tuple(tuple(row) for row in rows)
        if any(sum(row, Fraction()) for row in generator):
            raise AssertionError("projected generator row does not sum to zero")
        generators[channel.identifier] = generator
        channel_records.append({
            "channel": channel.identifier,
            "construction": "literal conditional-rule application",
            "per_match_normalization": str(channel.per_match),
            "source_states_checked_by_application": len(states),
            "generated_nonidentity_products": generated_products,
            "raw_injective_matches": raw_matches,
            "projected_transition_classes": projected_classes,
            "sources": source_records,
        })

    return FiniteRuleProjection(
        states,
        generators,
        {
            "schema_version": 1,
            "status": "PASS",
            "method": "literal conditional-DPO application followed by declared quotient projection",
            "state_count": len(states),
            "channels": channel_records,
            "supplied_transition_or_delta_table": False,
        },
    )
